from __builtins__ import *
# 完整轮时间：3:46.886（2026-10-28，官方完整32轮，request 191）。

def lb_sunflowers():
    clear()
    set_world_size(32)
    quick_print("pair_farm_begin", get_time(), num_items(Items.Power))
    result = launch_farm(0, 16, get_time() + 400)
    quick_print("pair_farm_done", result, get_time(), num_items(Items.Power))


def launch_farm(pod, count, deadline):
    if not go(pod * 64 + 16, deadline):
        return False
    if count == 1:
        return farm(pod, deadline)
    half = count // 2
    def child():
        return launch_farm(pod + half, half, deadline)
    handle = spawn_drone(child)
    if handle == None:
        quick_print("pair_farm_failed", "launch", pod)
        return False
    local = launch_farm(pod, half, deadline)
    other = wait_for(handle)
    return local and other


def pause():
    for _ in range(32):
        pass


def go(index, deadline):
    tx, ty = points[index]
    dx = (tx - get_pos_x()) % 32
    direction = East
    if dx > 16:
        direction = West
        dx = 32 - dx
    for _ in range(dx):
        if get_time() > deadline or not move(direction):
            return False
    dy = (ty - get_pos_y()) % 32
    direction = North
    if dy > 16:
        direction = South
        dy = 32 - dy
    for _ in range(dy):
        if get_time() > deadline or not move(direction):
            return False
    return True


def water():
    if get_water() < 0.425 and num_items(Items.Water) > 32:
        return use_item(Items.Water)
    return True


def hay_barrier(marker, phase, deadline):
    if not go(marker, deadline):
        return False
    if get_ground_type() == Grounds.Soil:
        till()
    while not can_harvest():
        if get_time() > deadline:
            return False
        pause()
    if not harvest():
        return False
    while num_items(Items.Hay) < phase * 32 * 512:
        if get_time() > deadline:
            return False
        pause()
    return True


def seed(pod, side, cycle, deadline):
    buckets = []
    for _ in range(9):
        buckets.append([])
    began = get_time()
    for cell in range(side * 32, side * 32 + 32):
        if not go(pod * 64 + cell, deadline):
            return None
        if cell % 32 == 16:
            continue
        if get_ground_type() != Grounds.Soil:
            till()
        if not plant(Entities.Sunflower):
            return None
        petals = measure()
        if petals == None or petals < 7 or petals > 15:
            return None
        buckets[15 - petals].append(cell)
        if not water():
            return None
    seeded = get_time()
    if not hay_barrier(pod * 64 + side * 32 + 16, cycle * 2 + 1, deadline):
        return None
    quick_print("pair_seed", pod, side, cycle, began, seeded, get_time())
    return buckets


def routes(pod, buckets):
    positions = [16, 48]
    mapping = codes[pod]
    plans = [[], []]
    for rank in range(9):
        cells = buckets[rank]
        assigned = [[], []]
        if len(cells) > 0:
            mapped = []
            for cell in cells:
                mapped.append(mapping[cell])
            prefix = [0]
            for i in range(1, len(cells)):
                prefix.append(prefix[-1] + table[mapped[i - 1]][mapped[i]] + 1)
            order = [0, 1]
            if (positions[0] - cells[0]) % 64 > (positions[1] - cells[0]) % 64:
                order = [1, 0]
            cut = split(positions, cells, order, prefix, mapped, mapping)
            stops = [cut, len(cells)]
            index = 0
            for j in range(2):
                worker = order[j]
                stop = stops[j]
                if stop > index:
                    assigned[worker] = cells[index:stop]
                    positions[worker] = cells[stop - 1]
                index = stop
        plans[0].append(assigned[0])
        plans[1].append(assigned[1])
    return plans


def consume_signal(base, rank, deadline):
    # 只有本轮种花结束后才进入；临时南瓜不提供伴生或成熟收益。
    if get_ground_type() != Grounds.Soil:
        till()
    if not plant(Entities.Pumpkin):
        return False
    if not harvest():
        return False
    while num_items(Items.Carrot) > base - (rank + 1) * 32 * 512:
        if get_time() > deadline:
            return False
        pause()
    return True


def collect(pod, side, cycle, plan, base, deadline):
    marker = pod * 64 + side * 32 + 16
    if not hay_barrier(marker, cycle * 2 + 2, deadline):
        return False
    harvested = 0
    for rank in range(9):
        began = get_time()
        for cell in plan[rank]:
            if not go(pod * 64 + cell, deadline):
                return False
            while not can_harvest():
                if get_time() > deadline:
                    return False
                if not water():
                    return False
                pause()
            if not harvest():
                return False
            harvested += 1
        if not consume_signal(base, rank, deadline):
            return False
        if pod == 0 and side == 0:
            quick_print("pair_rank_end", cycle, rank, began, get_time(), num_items(Items.Power), num_items(Items.Water))
    if not go(marker, deadline):
        return False
    if get_ground_type() == Grounds.Soil:
        till()
    quick_print("pair_collect", pod, side, cycle, harvested, get_time())
    return True


def farm(pod, deadline):
    for cycle in range(14):
        wave_deadline = min(deadline, get_time() + 45)
        began = get_time()
        def second_seed():
            return seed(pod, 1, cycle, wave_deadline)
        handle = spawn_drone(second_seed)
        if handle == None:
            quick_print("pair_farm_failed", "seed_spawn", pod, cycle)
            return False
        first = seed(pod, 0, cycle, wave_deadline)
        second = wait_for(handle)
        if first == None or second == None:
            quick_print("pair_farm_failed", "seed", pod, cycle)
            return False
        base = num_items(Items.Carrot)
        for rank in range(9):
            first[rank] = first[rank] + second[rank]
        planning = get_time()
        plans = routes(pod, first)
        planned = get_time()
        def second_collect():
            return collect(pod, 1, cycle, plans[1], base, wave_deadline)
        handle = spawn_drone(second_collect)
        if handle == None:
            quick_print("pair_farm_failed", "collect_spawn", pod, cycle)
            return False
        local = collect(pod, 0, cycle, plans[0], base, wave_deadline)
        other = wait_for(handle)
        quick_print("pair_wave", pod, cycle, began, planning, planned, get_time(), num_items(Items.Power))
        if not local or not other:
            quick_print("pair_farm_failed", "collect", pod, cycle)
            return False
    return True


def split(positions, cells, order, prefix, mapped, mapping):
    n = len(cells)
    first = table[mapping[positions[order[0]]]][mapped[0]] + 1
    row = table[mapping[positions[order[1]]]]
    end = prefix[-1]
    low = 0
    high = n
    while low < high:
        middle = (low + high) // 2
        left = 0
        if middle > 0:
            left = first + prefix[middle - 1]
        right = row[mapped[middle]] + 1 + end - prefix[middle]
        if left < right:
            low = middle + 1
        else:
            high = middle
    right = 0
    if low < n:
        right = row[mapped[low]] + 1 + end - prefix[low]
    left = 0
    if low > 0:
        left = first + prefix[low - 1]
    best = max(left, right)
    cut = low
    if low > 0:
        index = low - 1
        left = 0
        if index > 0:
            left = first + prefix[index - 1]
        right = row[mapped[index]] + 1 + end - prefix[index]
        if max(left, right) <= best:
            cut = index
    return cut

